"""Deliberately broken starting point for Flow B's repair demo."""

import csv
import sys


def summarize(path: str) -> dict[str, int]:
    counts = {"ok": 0, "malformed": 0, "high": 0}
    with open(path, newline="", encoding="utf-8") as handle:
        for row in csv.DictReader(handle):
            # Fix Bug 1: Check if temperature exists and is not empty
            temp_str = row["temperature_c"]
            if temp_str is None or temp_str.strip() == "":
                counts["malformed"] += 1
                continue
            temperature = float(temp_str)
            # Fix Bug 2: 350.0 is the inclusive upper limit, so it should be "ok"
            if temperature > 350.0:
                counts["high"] += 1
            else:
                counts["ok"] += 1
    return counts


if __name__ == "__main__":
    print(summarize(sys.argv[1]))
